UPDATE problems SET chapter_id = '4fb48180-724d-4250-acde-e3277c2c9ed6', topic_id = '196ffab0-6cca-4898-8909-a56000ff9fd7', curriculum_id = 'as', topic_code = '6.1', syllabus_cite = '9702 coursebook 6.1 · The idea of momentum', problem_number = 1, "order" = 1, question_text = 'Which of these is a correct SI unit for momentum?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'kg m s⁻¹', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Momentum p = mv, so its unit is kg × m s⁻¹ = kg m s⁻¹. (This is the same as N s, because 1 N = 1 kg m s⁻².) Common mistake: writing kg m s⁻², which is the unit of FORCE (mass × acceleration), not momentum.', points = 1 WHERE id = '63c610b2-0197-4735-96d1-82a63aa4efbb';
UPDATE problem_options SET problem_id = '63c610b2-0197-4735-96d1-82a63aa4efbb', option_text = 'kg m s⁻²', option_letter = 'A', is_correct = false, "order" = 0 WHERE id = '54698210-6e2d-4bcb-8829-6ea60079c4a9';
UPDATE problem_options SET problem_id = '63c610b2-0197-4735-96d1-82a63aa4efbb', option_text = 'kg m² s⁻²', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = 'db36a3b8-09c2-4d20-8a3a-6cfffd3a5a82';
UPDATE problem_options SET problem_id = '63c610b2-0197-4735-96d1-82a63aa4efbb', option_text = 'kg m s⁻¹', option_letter = 'C', is_correct = true, "order" = 2 WHERE id = 'b61d39e9-e0c2-4b1e-91c4-fca5f3f2db17';
UPDATE problem_options SET problem_id = '63c610b2-0197-4735-96d1-82a63aa4efbb', option_text = 'N s⁻¹', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = '0f5402a2-7695-40b7-8d3b-b366617ee0fa';
UPDATE problems SET chapter_id = '4fb48180-724d-4250-acde-e3277c2c9ed6', topic_id = '196ffab0-6cca-4898-8909-a56000ff9fd7', curriculum_id = 'as', topic_code = '6.1', syllabus_cite = '9702 coursebook 6.1 · The idea of momentum', problem_number = 2, "order" = 2, question_text = 'A cheetah of mass 55 kg sprints at 28 m s⁻¹. Calculate the magnitude of its momentum.', question_image_url = 'diagram:mom6-6-1-q2', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '1540', answer_unit = 'kg m/s', answer_unit_required = false, answer_tolerance = 0.05, answer_sign_sensitive = false, explanation = 'p = mv = 55 × 28 = 1540 kg m s⁻¹. Common mistake: using ½mv² (kinetic energy) instead of mv.', points = 1 WHERE id = '0c5ab716-adef-45c9-8552-dce792d7c57f';
UPDATE problems SET chapter_id = '4fb48180-724d-4250-acde-e3277c2c9ed6', topic_id = '196ffab0-6cca-4898-8909-a56000ff9fd7', curriculum_id = 'as', topic_code = '6.1', syllabus_cite = '9702 coursebook 6.1 · The idea of momentum', problem_number = 3, "order" = 3, question_text = 'A honeybee of mass 0.10 g flies at 7.0 m s⁻¹. Calculate its momentum.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '7e-4', answer_unit = 'kg m/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Convert the mass to kilograms first: 0.10 g = 0.10 × 10⁻³ kg = 1.0 × 10⁻⁴ kg. Then p = mv = 1.0 × 10⁻⁴ × 7.0 = 7.0 × 10⁻⁴ kg m s⁻¹. Common mistake: leaving the mass in grams, which gives an answer 1000 times too large (0.70).', points = 1 WHERE id = '49b7f02b-4edc-4d85-bb9d-78e67c1461c9';
UPDATE problems SET chapter_id = '4fb48180-724d-4250-acde-e3277c2c9ed6', topic_id = '196ffab0-6cca-4898-8909-a56000ff9fd7', curriculum_id = 'as', topic_code = '6.1', syllabus_cite = '9702 coursebook 6.1 · The idea of momentum', problem_number = 4, "order" = 4, question_text = 'A curling stone of mass 20 kg slides across the ice with a momentum of 46 kg m s⁻¹. Calculate its speed.', question_image_url = 'diagram:mom6-6-1-q4', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '2.3', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Rearrange p = mv: v = p ÷ m = 46 ÷ 20 = 2.3 m s⁻¹. Common mistake: multiplying instead of dividing (46 × 20 = 920).', points = 1 WHERE id = 'c73f86c3-0b06-49b9-820c-de2d4b88efea';
UPDATE problems SET chapter_id = '4fb48180-724d-4250-acde-e3277c2c9ed6', topic_id = '196ffab0-6cca-4898-8909-a56000ff9fd7', curriculum_id = 'as', topic_code = '6.1', syllabus_cite = '9702 coursebook 6.1 · The idea of momentum', problem_number = 6, "order" = 6, question_text = 'A hailstone falls at 25 m s⁻¹ with a momentum of 0.050 kg m s⁻¹. Calculate its mass.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '0.002', answer_unit = 'kg', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'm = p ÷ v = 0.050 ÷ 25 = 0.0020 kg (that is 2.0 g). Common mistake: dividing the speed by the momentum (25 ÷ 0.050 = 500), which gives an impossibly heavy hailstone — always sense-check the size of your answer.', points = 1 WHERE id = '81db1a0f-7046-4b02-8cf6-11b8622053d8';
UPDATE problems SET chapter_id = '4fb48180-724d-4250-acde-e3277c2c9ed6', topic_id = '196ffab0-6cca-4898-8909-a56000ff9fd7', curriculum_id = 'as', topic_code = '6.1', syllabus_cite = '9702 coursebook 6.1 · The idea of momentum', problem_number = 7, "order" = 7, question_text = 'A tennis ball of mass 57 g hits a wall at 30 m s⁻¹ and rebounds along the same line at 22 m s⁻¹. Calculate the magnitude of the change in its momentum.', question_image_url = 'diagram:mom6-6-1-q7', difficulty_level = 2, answer_type = 'numeric'::answer_type, answer_correct = '2.964', answer_unit = 'kg m/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Take towards the wall as positive. Initial p = 0.057 × (+30) = +1.71 kg m s⁻¹. Final p = 0.057 × (−22) = −1.25 kg m s⁻¹. Change = final − initial = −1.25 − 1.71 = −2.96 kg m s⁻¹, so the magnitude is 2.96 kg m s⁻¹. Common mistake: subtracting the speeds (30 − 22 = 8) and getting 0.46 — the ball reverses, so the speeds ADD.', points = 2 WHERE id = '4e0a0da9-4d86-4fab-b7a6-14336c22548e';
UPDATE problems SET chapter_id = '4fb48180-724d-4250-acde-e3277c2c9ed6', topic_id = '42c67aa7-36ea-56ea-881a-771edd16371c', curriculum_id = 'as', topic_code = '6.2', syllabus_cite = '9702 coursebook 6.2 · Conservation of momentum and collisions', problem_number = 1, "order" = 1, question_text = 'Which statement is the principle of conservation of momentum?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'The total momentum of a system remains constant, provided no resultant external force acts on it', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'The total momentum of a system of interacting objects stays constant, provided no resultant external force acts on the system. It holds for every collision and explosion, elastic or not. Common mistake: thinking each object keeps its own momentum, or that momentum is conserved only in elastic collisions.', points = 1 WHERE id = 'ceacc00b-45f3-4fb6-9d0e-312d622d7fa7';
UPDATE problem_options SET problem_id = 'ceacc00b-45f3-4fb6-9d0e-312d622d7fa7', option_text = 'The total momentum of a system remains constant, provided no resultant external force acts on it', option_letter = 'A', is_correct = true, "order" = 0 WHERE id = 'ab714c98-fbeb-4f32-b606-2b5dfdbbc210';
UPDATE problem_options SET problem_id = 'ceacc00b-45f3-4fb6-9d0e-312d622d7fa7', option_text = 'The momentum of each object in a collision remains constant', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = '95f957e8-cf22-4c78-b1a9-10293451348c';
UPDATE problem_options SET problem_id = 'ceacc00b-45f3-4fb6-9d0e-312d622d7fa7', option_text = 'Momentum is conserved only when a collision is elastic', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = '0f5e32b8-dca5-4257-b71a-483aa3d3447e';
UPDATE problem_options SET problem_id = 'ceacc00b-45f3-4fb6-9d0e-312d622d7fa7', option_text = 'The total kinetic energy of a system remains constant in a collision', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = '404df94c-c228-4c82-9dd6-7afb4558362d';
UPDATE problems SET chapter_id = '4fb48180-724d-4250-acde-e3277c2c9ed6', topic_id = '42c67aa7-36ea-56ea-881a-771edd16371c', curriculum_id = 'as', topic_code = '6.2', syllabus_cite = '9702 coursebook 6.2 · Conservation of momentum and collisions', problem_number = 2, "order" = 2, question_text = 'A trolley of mass 0.50 kg moving at 4.0 m s⁻¹ collides with a stationary trolley of mass 1.5 kg. They stick together. Calculate their speed after the collision.', question_image_url = 'diagram:mom6-6-2-q2', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '1', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Momentum before = 0.50 × 4.0 + 1.5 × 0 = 2.0 kg m s⁻¹. After, the combined mass is 2.0 kg: 2.0 × v = 2.0, so v = 1.0 m s⁻¹. Common mistake: dividing by 1.5 kg (only the second trolley) instead of the combined 2.0 kg.', points = 1 WHERE id = '1bd9e80f-574a-4f8d-b0ae-314f47aeb4a4';
UPDATE problems SET chapter_id = '4fb48180-724d-4250-acde-e3277c2c9ed6', topic_id = '42c67aa7-36ea-56ea-881a-771edd16371c', curriculum_id = 'as', topic_code = '6.2', syllabus_cite = '9702 coursebook 6.2 · Conservation of momentum and collisions', problem_number = 3, "order" = 3, question_text = 'A railway wagon of mass 30 000 kg rolls at 2.0 m s⁻¹ into a stationary wagon of mass 20 000 kg. The wagons couple together. Calculate their speed just after coupling.', question_image_url = 'diagram:mom6-6-2-q3', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '1.2', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Momentum before = 30 000 × 2.0 = 60000 kg m s⁻¹. After: 50 000 × v = 60 000, so v = 1.2 m s⁻¹. Common mistake: averaging the speeds ((2.0 + 0) ÷ 2 = 1.0) — this only works when the masses are equal.', points = 1 WHERE id = 'fc896940-00cb-471c-a03b-ee19dce109ed';
UPDATE problems SET chapter_id = '4fb48180-724d-4250-acde-e3277c2c9ed6', topic_id = '42c67aa7-36ea-56ea-881a-771edd16371c', curriculum_id = 'as', topic_code = '6.2', syllabus_cite = '9702 coursebook 6.2 · Conservation of momentum and collisions', problem_number = 4, "order" = 4, question_text = 'Two ice skaters, of mass 60 kg and 75 kg, stand at rest facing each other and push apart. The 60 kg skater moves off at 2.5 m s⁻¹. Calculate the speed of the 75 kg skater.', question_image_url = 'diagram:mom6-6-2-q4', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '2', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Total momentum before = 0, so after the push the momenta are equal and opposite: 60 × 2.5 = 75 × v, v = 150 ÷ 75 = 2.0 m s⁻¹, in the opposite direction. Common mistake: thinking the heavier skater moves faster because they "push harder" — the forces are equal and opposite (Newton''s third law).', points = 1 WHERE id = 'dd5f8c99-8730-4418-b2b3-9243c737af4f';
UPDATE problems SET chapter_id = '4fb48180-724d-4250-acde-e3277c2c9ed6', topic_id = '42c67aa7-36ea-56ea-881a-771edd16371c', curriculum_id = 'as', topic_code = '6.2', syllabus_cite = '9702 coursebook 6.2 · Conservation of momentum and collisions', problem_number = 5, "order" = 5, question_text = 'A ball is released and falls towards the ground, gaining momentum. Which statement explains why this does NOT break the principle of conservation of momentum?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'The Earth gains an equal and opposite momentum, so the total momentum of ball + Earth is constant', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'The ball on its own is not an isolated system: the Earth''s gravitational pull is an external force on it. Take the ball AND the Earth as the system: the ball pulls the Earth up with an equal and opposite force, so the Earth gains an equal momentum upwards and the total stays zero. The Earth''s huge mass means its velocity change is far too small to notice. Common mistake: concluding that momentum is not conserved when one object speeds up.', points = 1 WHERE id = '20a07229-d500-41da-8a4b-048d76d04726';
UPDATE problem_options SET problem_id = '20a07229-d500-41da-8a4b-048d76d04726', option_text = 'Momentum is only conserved in horizontal motion', option_letter = 'A', is_correct = false, "order" = 0 WHERE id = 'f377cc0c-fc5a-42ab-866f-8582bf9b5dcf';
UPDATE problem_options SET problem_id = '20a07229-d500-41da-8a4b-048d76d04726', option_text = 'Gravity is not a force, so it cannot change momentum', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = '6497ae06-13d5-4acf-8dd6-94d8f3a97ade';
UPDATE problem_options SET problem_id = '20a07229-d500-41da-8a4b-048d76d04726', option_text = 'The ball loses potential energy, which balances the momentum gained', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = 'a1b68b04-23d7-41ee-a262-2a984237017b';
UPDATE problem_options SET problem_id = '20a07229-d500-41da-8a4b-048d76d04726', option_text = 'The Earth gains an equal and opposite momentum, so the total momentum of ball + Earth is constant', option_letter = 'D', is_correct = true, "order" = 3 WHERE id = 'aeb892f2-9c3d-47da-9b88-bac08e49938d';
UPDATE problems SET chapter_id = '4fb48180-724d-4250-acde-e3277c2c9ed6', topic_id = '42c67aa7-36ea-56ea-881a-771edd16371c', curriculum_id = 'as', topic_code = '6.2', syllabus_cite = '9702 coursebook 6.2 · Conservation of momentum and collisions', problem_number = 6, "order" = 6, question_text = 'A 2.0 kg trolley moving at 3.0 m s⁻¹ hits a stationary trolley and they stick together, moving at 1.2 m s⁻¹. Calculate the mass of the second trolley.', question_image_url = 'diagram:mom6-6-2-q6', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '3', answer_unit = 'kg', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Momentum before = 2.0 × 3.0 = 6.0 kg m s⁻¹. After: (2.0 + m) × 1.2 = 6.0, so 2.0 + m = 5.0 kg and m = 3.0 kg. Common mistake: giving 5.0 kg — that is the COMBINED mass, not the second trolley alone.', points = 1 WHERE id = '46f89dd8-9b4b-4996-8c2a-4a22888055cf';
UPDATE problems SET chapter_id = '4fb48180-724d-4250-acde-e3277c2c9ed6', topic_id = '42c67aa7-36ea-56ea-881a-771edd16371c', curriculum_id = 'as', topic_code = '6.2', syllabus_cite = '9702 coursebook 6.2 · Conservation of momentum and collisions', problem_number = 7, "order" = 7, question_text = 'A car of mass 1200 kg travelling east at 20 m s⁻¹ collides head-on with a car of mass 1600 kg travelling west at 12 m s⁻¹. The cars lock together. Taking east as positive, calculate their velocity just after the collision, including its sign.', question_image_url = 'diagram:mom6-6-2-q7', difficulty_level = 2, answer_type = 'numeric'::answer_type, answer_correct = '1.714', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = true, explanation = 'Momentum before = 1200 × (+20) + 1600 × (−12) = 24000 − 19200 = +4800 kg m s⁻¹. After: 2800 × v = 4800, v = +1.71 m s⁻¹ (east). Common mistake: giving the westbound momentum a positive sign too, which gives 15.4 m s⁻¹.', points = 2 WHERE id = 'c5c1f907-6937-4293-9a88-5f2618ec0a32';
UPDATE problems SET chapter_id = '4fb48180-724d-4250-acde-e3277c2c9ed6', topic_id = '42c67aa7-36ea-56ea-881a-771edd16371c', curriculum_id = 'as', topic_code = '6.2', syllabus_cite = '9702 coursebook 6.2 · Conservation of momentum and collisions', problem_number = 11, "order" = 11, question_text = 'A rifle "kicks" much less painfully when it is held tightly against the shoulder than when it is held loosely. Which explanation is correct?', question_image_url = NULL, difficulty_level = 2, answer_type = 'multiple_choice'::answer_type, answer_correct = 'The recoil momentum is shared by the rifle and the body together, so the recoil speed is much smaller', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'The bullet''s forward momentum is fixed, so the rifle (plus whatever moves with it) must gain an equal backward momentum. Held tightly, the rifle and the shooter''s body move together, so the recoiling mass is much larger and the recoil SPEED much smaller: the body is not hit by a fast-moving rifle. Common mistake: thinking holding tightly reduces the recoil momentum — it cannot, because momentum is conserved.', points = 2 WHERE id = 'd27334c0-2b90-478f-9932-8974e2a1e0d7';
UPDATE problem_options SET problem_id = 'd27334c0-2b90-478f-9932-8974e2a1e0d7', option_text = 'Holding tightly reduces the momentum given to the bullet', option_letter = 'A', is_correct = false, "order" = 0 WHERE id = 'f66f17b6-a982-4be4-86cb-8ace8d1fcab9';
UPDATE problem_options SET problem_id = 'd27334c0-2b90-478f-9932-8974e2a1e0d7', option_text = 'The recoil momentum is shared by the rifle and the body together, so the recoil speed is much smaller', option_letter = 'B', is_correct = true, "order" = 1 WHERE id = 'e1d628b0-a764-43c4-affe-5048d814fa37';
UPDATE problem_options SET problem_id = 'd27334c0-2b90-478f-9932-8974e2a1e0d7', option_text = 'Holding tightly makes momentum not conserved', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = '51803727-c8a7-4a2f-a3cd-75bb934f7012';
UPDATE problem_options SET problem_id = 'd27334c0-2b90-478f-9932-8974e2a1e0d7', option_text = 'The shoulder absorbs the bullet''s kinetic energy', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = 'acdfd30a-7071-4145-9e40-800f9d0eda9e';
UPDATE problems SET chapter_id = '4fb48180-724d-4250-acde-e3277c2c9ed6', topic_id = 'ac47b348-a080-47b5-a3b9-a2a40915eb56', curriculum_id = 'as', topic_code = '6.3', syllabus_cite = '9702 coursebook 6.3 · Understanding collisions', problem_number = 1, "order" = 1, question_text = 'What is meant by an elastic collision?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'A collision in which the total kinetic energy is conserved', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'An elastic collision is one in which the total kinetic energy of the objects is the same after the collision as before. Momentum is conserved in EVERY collision, so that is not what makes it elastic. Common mistake: defining "elastic" as "momentum is conserved", or as "the objects bounce apart" (objects can bounce apart and still lose kinetic energy).', points = 1 WHERE id = '0a6db659-eca3-44af-bfda-fde05341be07';
UPDATE problem_options SET problem_id = '0a6db659-eca3-44af-bfda-fde05341be07', option_text = 'A collision in which momentum is conserved', option_letter = 'A', is_correct = false, "order" = 0 WHERE id = '7025503a-7757-4ea4-b9d4-470e3124323c';
UPDATE problem_options SET problem_id = '0a6db659-eca3-44af-bfda-fde05341be07', option_text = 'Any collision in which the objects bounce apart', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = 'e33f1e35-94dc-4e7e-8985-b6f6b2f155d2';
UPDATE problem_options SET problem_id = '0a6db659-eca3-44af-bfda-fde05341be07', option_text = 'A collision in which the total kinetic energy is conserved', option_letter = 'C', is_correct = true, "order" = 2 WHERE id = 'c96771fb-3312-455b-ac8e-767c83d354d5';
UPDATE problem_options SET problem_id = '0a6db659-eca3-44af-bfda-fde05341be07', option_text = 'A collision in which the objects stick together', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = 'eefd4ad3-2d21-4023-8686-37194dd391bd';
UPDATE problems SET chapter_id = '4fb48180-724d-4250-acde-e3277c2c9ed6', topic_id = 'ac47b348-a080-47b5-a3b9-a2a40915eb56', curriculum_id = 'as', topic_code = '6.3', syllabus_cite = '9702 coursebook 6.3 · Understanding collisions', problem_number = 2, "order" = 2, question_text = 'Which statement describes a perfectly inelastic collision?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'The objects stick together and move with a common velocity', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'In a perfectly inelastic collision the objects stick together and move off with a common velocity. This loses the most kinetic energy that conservation of momentum allows (though not necessarily ALL of it). Common mistake: thinking all kinetic energy must be lost — the stuck-together objects usually keep moving.', points = 1 WHERE id = '21289c9c-721c-4376-a974-4352171631f3';
UPDATE problem_options SET problem_id = '21289c9c-721c-4376-a974-4352171631f3', option_text = 'The objects stick together and move with a common velocity', option_letter = 'A', is_correct = true, "order" = 0 WHERE id = 'ba7f123a-3527-44d2-800c-928f42f1da21';
UPDATE problem_options SET problem_id = '21289c9c-721c-4376-a974-4352171631f3', option_text = 'All of the kinetic energy is always lost', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = '89457bfd-17ed-4bc8-9afb-ca2c3068a6f2';
UPDATE problem_options SET problem_id = '21289c9c-721c-4376-a974-4352171631f3', option_text = 'Momentum is not conserved', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = '0462fe49-1333-4d2c-9b6a-d046cb6ad819';
UPDATE problem_options SET problem_id = '21289c9c-721c-4376-a974-4352171631f3', option_text = 'The objects separate with the same relative speed as they approached', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = '10902dd6-e1ec-4212-8a8d-3f4ce5eb0ebe';
UPDATE problems SET chapter_id = '4fb48180-724d-4250-acde-e3277c2c9ed6', topic_id = 'ac47b348-a080-47b5-a3b9-a2a40915eb56', curriculum_id = 'as', topic_code = '6.3', syllabus_cite = '9702 coursebook 6.3 · Understanding collisions', problem_number = 3, "order" = 3, question_text = 'A 2.0 kg trolley moving at 3.0 m s⁻¹ collides with a stationary 1.0 kg trolley. They stick together and move off at 2.0 m s⁻¹. Calculate the kinetic energy lost in the collision.', question_image_url = 'diagram:mom6-6-3-q3', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '3', answer_unit = 'J', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'KE before = ½ × 2.0 × 3.0² = 9.0 J. KE after = ½ × 3.0 × 2.0² = 6.0 J (use the combined mass). Lost = 9.0 − 6.0 = 3.0 J. Common mistake: using 2.0 kg instead of the combined 3.0 kg after the collision.', points = 1 WHERE id = '813fbd8d-8f13-47e2-a168-f1db25c9f36e';
UPDATE problems SET chapter_id = '4fb48180-724d-4250-acde-e3277c2c9ed6', topic_id = 'ac47b348-a080-47b5-a3b9-a2a40915eb56', curriculum_id = 'as', topic_code = '6.3', syllabus_cite = '9702 coursebook 6.3 · Understanding collisions', problem_number = 4, "order" = 4, question_text = 'Ball A moves to the right at 5.0 m s⁻¹. Ball B moves to the left at 2.0 m s⁻¹, directly towards A. Calculate their relative speed of approach.', question_image_url = 'diagram:mom6-6-3-q4', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '7', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Moving towards each other, the speeds add: 5.0 + 2.0 = 7.0 m s⁻¹. (With right positive: 5.0 − (−2.0) = 7.0.) Common mistake: subtracting (5.0 − 2.0 = 3.0), which is the relative speed only when both move the SAME way.', points = 1 WHERE id = 'cd4ed4b8-4fd9-414e-b8cc-d0a8b223975f';
UPDATE problems SET chapter_id = '4fb48180-724d-4250-acde-e3277c2c9ed6', topic_id = 'ac47b348-a080-47b5-a3b9-a2a40915eb56', curriculum_id = 'as', topic_code = '6.3', syllabus_cite = '9702 coursebook 6.3 · Understanding collisions', problem_number = 6, "order" = 6, question_text = 'Two objects move in the same direction along a line: the one behind at 6.0 m s⁻¹ and the one in front at 1.0 m s⁻¹. The faster one catches up and they collide elastically. Calculate their relative speed of separation after the collision.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '5', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Relative speed of approach = 6.0 − 1.0 = 5.0 m s⁻¹ (same direction, so subtract). For an elastic collision, relative speed of separation = relative speed of approach = 5.0 m s⁻¹. Common mistake: adding the speeds (7.0) even though the objects move the same way.', points = 1 WHERE id = '4b74f3fa-23a0-4cd7-b5e8-884edb38b15a';
UPDATE problems SET chapter_id = '4fb48180-724d-4250-acde-e3277c2c9ed6', topic_id = 'ac47b348-a080-47b5-a3b9-a2a40915eb56', curriculum_id = 'as', topic_code = '6.3', syllabus_cite = '9702 coursebook 6.3 · Understanding collisions', problem_number = 8, "order" = 8, question_text = 'A 1.2 kg trolley moving at 5.0 m s⁻¹ collides with an identical stationary trolley and they stick together. Calculate the percentage of the kinetic energy that is lost.', question_image_url = NULL, difficulty_level = 2, answer_type = 'numeric'::answer_type, answer_correct = '50', answer_unit = '%', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Common speed: 1.2 × 5.0 = 2.4v, v = 2.5 m s⁻¹. KE before = ½ × 1.2 × 5.0² = 15 J. KE after = ½ × 2.4 × 2.5² = 7.50 J. Lost = 7.50 J, which is 50%. (For equal masses sticking, half the kinetic energy is always lost.) Common mistake: assuming that because the speed halves, the kinetic energy halves for each trolley and so nothing is lost overall.', points = 2 WHERE id = 'a0a3d99a-f564-48d7-b7c9-5331f9914e1c';
