INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2e3ef44a-2dff-5892-bdaa-174cd15d6bcc', '4fb48180-724d-4250-acde-e3277c2c9ed6', '196ffab0-6cca-4898-8909-a56000ff9fd7', 'as', '6.1', '9702 coursebook 6.1 · The idea of momentum', 5, 5, 'A ball moves east at 4.0 m s⁻¹. A moment later it moves west at 4.0 m s⁻¹. Which statement is correct?', NULL, 1, 'multiple_choice'::answer_type, 'Its momentum has changed, because its direction has changed', NULL, false, NULL, false, 'Momentum is a vector: it has the direction of the velocity. The SIZE of the momentum is the same, but its direction has reversed, so the momentum has changed (taking east as positive it went from +4m to −4m). Common mistake: thinking that "same speed" means "same momentum" — that is only true for a scalar like kinetic energy.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('afa3187f-a051-5cbc-93d1-5051a6e901c7', '2e3ef44a-2dff-5892-bdaa-174cd15d6bcc', 'Its momentum has changed, because its direction has changed', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('d63f3f2a-831c-5cb5-9a5f-ff89a632316d', '2e3ef44a-2dff-5892-bdaa-174cd15d6bcc', 'Its momentum is unchanged, because its speed is unchanged', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('1f590a69-220d-5fa8-8e76-ca4d6591d324', '2e3ef44a-2dff-5892-bdaa-174cd15d6bcc', 'Its momentum has become zero', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('0b9aafd8-652a-5700-a57c-a8f0d586c0c1', '2e3ef44a-2dff-5892-bdaa-174cd15d6bcc', 'Its kinetic energy has changed, but its momentum has not', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e18c355b-a21f-576c-bca0-c7c9916ee54c', '4fb48180-724d-4250-acde-e3277c2c9ed6', '196ffab0-6cca-4898-8909-a56000ff9fd7', 'as', '6.1', '9702 coursebook 6.1 · The idea of momentum', 8, 8, 'A car of mass 1200 kg travels north at 15 m s⁻¹. A lorry of mass 9000 kg travels south at 2.5 m s⁻¹. Calculate the magnitude of the total momentum of the car and lorry together.', 'diagram:mom6-6-1-q8', 2, 'numeric'::answer_type, '4500', 'kg m/s', false, NULL, false, 'Take north as positive. Car: +1200 × 15 = +18000 kg m s⁻¹. Lorry: 9000 × (−2.5) = −22500 kg m s⁻¹. Total = 18000 − 22500 = −4500 kg m s⁻¹: a magnitude of 4500 kg m s⁻¹, directed SOUTH (the slow lorry has more momentum than the fast car). Common mistake: adding the two magnitudes (40 500) as if momentum were a scalar.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('aafc870d-dbf4-50bb-8132-a3710dc3984c', '4fb48180-724d-4250-acde-e3277c2c9ed6', '196ffab0-6cca-4898-8909-a56000ff9fd7', 'as', '6.1', '9702 coursebook 6.1 · The idea of momentum', 9, 9, 'A bullet of mass 10 g moves at 400 m s⁻¹. A ball of mass 1.0 kg moves at 4.0 m s⁻¹. Which statement is correct?', 'diagram:mom6-6-1-q9', 2, 'multiple_choice'::answer_type, 'They have equal momentum, but the bullet has 100 times more kinetic energy', NULL, false, NULL, false, 'Momentum: bullet 0.010 × 400 = 4.0 kg m s⁻¹, ball 1.0 × 4.0 = 4.0 kg m s⁻¹ — exactly equal. Kinetic energy: bullet ½ × 0.010 × 400² = 800 J, ball ½ × 1.0 × 4.0² = 8.0 J. Same momentum, but the bullet carries 100 times the energy, because Ek = p²/2m and the bullet''s mass is 100 times smaller. That is why the bullet does far more damage. Common mistake: assuming equal momentum means equal kinetic energy.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('fcc22aeb-9338-5f4e-9cc7-af0070eee3ea', 'aafc870d-dbf4-50bb-8132-a3710dc3984c', 'They have equal momentum and equal kinetic energy', 'A', false, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('037e9c0f-e001-5c9e-a6f5-580478c0adb6', 'aafc870d-dbf4-50bb-8132-a3710dc3984c', 'The bullet has 100 times more momentum than the ball', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('2acafd66-ef43-5831-a834-33a7e98da5d3', 'aafc870d-dbf4-50bb-8132-a3710dc3984c', 'The ball has more momentum, because it is heavier', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('88da234d-a140-56d7-9a14-ee15ff0cfad1', 'aafc870d-dbf4-50bb-8132-a3710dc3984c', 'They have equal momentum, but the bullet has 100 times more kinetic energy', 'D', true, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('6cd0eec5-5e33-5fe0-9287-adebec56b008', '4fb48180-724d-4250-acde-e3277c2c9ed6', '196ffab0-6cca-4898-8909-a56000ff9fd7', 'as', '6.1', '9702 coursebook 6.1 · The idea of momentum', 10, 10, 'A cricket ball of mass 0.16 kg has kinetic energy 72 J. Calculate its momentum.', NULL, 2, 'numeric'::answer_type, '4.8', 'kg m/s', false, NULL, false, 'Ek = ½mv² and p = mv combine to Ek = p²/2m, so p = √(2mEk) = √(2 × 0.16 × 72) = √23.04 = 4.8 kg m s⁻¹. (Check: v = p/m = 30 m s⁻¹, and ½ × 0.16 × 30² = 72 J.) Common mistake: forgetting the factor 2, giving √(0.16 × 72) = 3.4.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('274a4919-81fe-5814-b650-8e9f4e42f259', '4fb48180-724d-4250-acde-e3277c2c9ed6', '196ffab0-6cca-4898-8909-a56000ff9fd7', 'as', '6.1', '9702 coursebook 6.1 · The idea of momentum', 11, 11, 'A bowling ball of mass 5.0 kg and a football of mass 0.45 kg have the same momentum. The football moves at 20 m s⁻¹. Calculate the speed of the bowling ball.', 'diagram:mom6-6-1-q11', 2, 'numeric'::answer_type, '1.8', 'm/s', false, NULL, false, 'Momentum of the football = 0.45 × 20 = 9.0 kg m s⁻¹. The bowling ball has the same momentum, so v = 9.0 ÷ 5.0 = 1.8 m s⁻¹. Common mistake: assuming equal momentum means equal speed.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('5953089b-1216-5f58-abc6-1db273bd8fd0', '4fb48180-724d-4250-acde-e3277c2c9ed6', '196ffab0-6cca-4898-8909-a56000ff9fd7', 'as', '6.1', '9702 coursebook 6.1 · The idea of momentum', 12, 12, 'A ball is thrown vertically upwards. What is its momentum at the very top of its flight?', NULL, 2, 'multiple_choice'::answer_type, 'Zero', NULL, false, NULL, false, 'At the highest point the ball is instantaneously at rest (v = 0), so p = mv = 0. Its acceleration is still g downwards there, so its momentum immediately starts to grow again, now downwards. Common mistake: confusing "momentum is zero" with "force is zero" — gravity still acts at the top.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('1b6e0244-8af3-5b5e-821f-7d648a3fccf1', '5953089b-1216-5f58-abc6-1db273bd8fd0', 'Its maximum value', 'A', false, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('06ac04a6-ac37-54ff-8350-4c40b2f91988', '5953089b-1216-5f58-abc6-1db273bd8fd0', 'Zero', 'B', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ba48abcc-1595-541c-ba24-fb327465ec78', '5953089b-1216-5f58-abc6-1db273bd8fd0', 'Equal to its weight, mg', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('1212fda6-3721-5402-9d5d-72af36668dc2', '5953089b-1216-5f58-abc6-1db273bd8fd0', 'The same as when it was thrown', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('ec2aaced-bb8c-5ec6-ae4a-6f498ac1eebc', '4fb48180-724d-4250-acde-e3277c2c9ed6', '196ffab0-6cca-4898-8909-a56000ff9fd7', 'as', '6.1', '9702 coursebook 6.1 · The idea of momentum', 13, 13, 'The momentum of a car increases by a factor of 3. Its mass does not change. By what factor does its kinetic energy increase?', NULL, 2, 'numeric'::answer_type, '9', NULL, false, NULL, false, 'With m fixed, p = mv means v also triples. Ek = ½mv² ∝ v², so Ek increases by 3² = 9. Equivalently, Ek = p²/2m ∝ p². Common mistake: answering 3, as if kinetic energy were proportional to momentum.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('6ff4a40d-f018-5e87-a313-64ef35c89997', '4fb48180-724d-4250-acde-e3277c2c9ed6', '196ffab0-6cca-4898-8909-a56000ff9fd7', 'as', '6.1', '9702 coursebook 6.1 · The idea of momentum', 14, 14, 'The graph shows how the momentum of a 0.80 kg trolley changes as it is pushed from rest. (a) Calculate the maximum speed of the trolley. (b) Calculate the speed of the trolley at t = 1.5 s. (c) State what the gradient of the first section of the graph represents. Give only the answer to (b).', 'diagram:mom6-6-1-q14', 3, 'numeric'::answer_type, '1.5', 'm/s', false, NULL, false, '(a) Maximum p = 2.4 kg m s⁻¹, so v_max = 2.4 ÷ 0.80 = 3.0 m s⁻¹. (b) The momentum rises at a constant rate, gradient = 2.4 ÷ 3.0 = 0.80 kg m s⁻¹ per second, so at 1.5 s p = 0.80 × 1.5 = 1.2 kg m s⁻¹ and v = 1.2 ÷ 0.80 = 1.5 m s⁻¹. (c) The gradient is the rate of change of momentum, which equals the resultant force on the trolley (0.80 N here). Common mistake: reading the momentum (1.2) off the graph and giving that as the speed, forgetting to divide by the mass.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('35e19f3f-6eda-56e2-8ed0-91da30c19fae', '4fb48180-724d-4250-acde-e3277c2c9ed6', '196ffab0-6cca-4898-8909-a56000ff9fd7', 'as', '6.1', '9702 coursebook 6.1 · The idea of momentum', 15, 15, 'The Earth (mass 5.97 × 10²⁴ kg) moves in an approximately circular orbit of radius 1.50 × 10¹¹ m around the Sun, taking 365.25 days per orbit. (a) Calculate the Earth''s orbital speed. (b) Calculate the magnitude of the Earth''s momentum. (c) Explain why the Earth''s momentum is NOT constant, even though its speed is. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '1.783e29', 'kg m/s', false, NULL, false, '(a) T = 365.25 × 24 × 3600 = 3.156 × 10⁷ s. v = 2πr/T = 2π × 1.50 × 10¹¹ ÷ 3.156 × 10⁷ = 29900 m s⁻¹. (b) p = mv = 5.97 × 10²⁴ × 29900 = 1.78 × 10²⁹ kg m s⁻¹. (c) Momentum is a vector. The Earth''s direction of motion changes continuously around the orbit, so its momentum changes direction (the Sun''s gravitational pull is the force causing this change). Common mistake: using the time in days, not seconds, which makes v 86 400 times too large.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('5d364718-e880-53f4-a888-f08dcfe8392c', '4fb48180-724d-4250-acde-e3277c2c9ed6', '196ffab0-6cca-4898-8909-a56000ff9fd7', 'as', '6.1', '9702 coursebook 6.1 · The idea of momentum', 16, 16, 'A 50 g ball is dropped from a height of 1.80 m onto a hard floor and rebounds to a height of 1.25 m. Air resistance is negligible. (a) Calculate the speed of the ball just before it hits the floor. (b) Calculate the speed just after it leaves the floor. (c) Calculate the magnitude of the change in momentum of the ball during the bounce. Give only the answer to (c).', 'diagram:mom6-6-1-q16', 3, 'numeric'::answer_type, '0.5447', 'kg m/s', false, NULL, false, '(a) v = √(2gh) = √(2 × 9.81 × 1.80) = 5.94 m s⁻¹ (downwards). (b) v = √(2 × 9.81 × 1.25) = 4.95 m s⁻¹ (upwards). (c) Take up as positive: Δp = m(v_after − v_before) = 0.050 × (4.95 − (−5.94)) = 0.050 × 10.9 = 0.545 kg m s⁻¹. Common mistake: using 0.050 × (5.94 − 4.95) = 0.050, ignoring the reversal of direction.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a44c4d77-56c6-535c-867f-861f8c385616', '4fb48180-724d-4250-acde-e3277c2c9ed6', '196ffab0-6cca-4898-8909-a56000ff9fd7', 'as', '6.1', '9702 coursebook 6.1 · The idea of momentum', 17, 17, 'Which of the four objects shown would be hardest to stop in a given time? Choose the list that orders them from LARGEST to SMALLEST momentum.', 'diagram:mom6-6-1-q17', 3, 'multiple_choice'::answer_type, 'small car, sprinter, cyclist + bike, ice-hockey puck', NULL, false, NULL, false, 'Momentum decides how hard an object is to stop in a given time (the force needed is Δp/Δt). Car: 900 × 1.0 = 900 kg m s⁻¹. Sprinter: 80 × 10 = 800 kg m s⁻¹. Cyclist: 95 × 8.0 = 760 kg m s⁻¹. Puck: 0.17 × 45 = 7.65 kg m s⁻¹. Order: small car, sprinter, cyclist + bike, ice-hockey puck. The slow-rolling car beats the sprinter. Common mistake: ranking by speed (puck first) or by mass alone.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8671217e-3485-511c-8643-c66170c91670', 'a44c4d77-56c6-535c-867f-861f8c385616', 'ice-hockey puck, sprinter, cyclist + bike, small car', 'A', false, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('979cce0f-9ed0-5454-9290-ee56355f23ac', 'a44c4d77-56c6-535c-867f-861f8c385616', 'small car, cyclist + bike, sprinter, ice-hockey puck', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('9675691e-90ae-5d26-8469-73f4d9300e15', 'a44c4d77-56c6-535c-867f-861f8c385616', 'small car, sprinter, cyclist + bike, ice-hockey puck', 'C', true, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('18cc3c99-a9e3-50dd-9ddd-4d02b52de0f8', 'a44c4d77-56c6-535c-867f-861f8c385616', 'sprinter, cyclist + bike, small car, ice-hockey puck', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('5c9e4aba-7128-5aa7-9525-0d6354b73b9d', '4fb48180-724d-4250-acde-e3277c2c9ed6', '196ffab0-6cca-4898-8909-a56000ff9fd7', 'as', '6.1', '9702 coursebook 6.1 · The idea of momentum', 18, 18, 'Three gliders move along a straight air track. Glider A (0.20 kg) moves at +0.60 m s⁻¹, glider B (0.30 kg) moves at −0.40 m s⁻¹ and glider C (0.50 kg) moves with an unknown velocity. The total momentum of the three gliders is +0.15 kg m s⁻¹. (a) Show that the momenta of A and B cancel. (b) Calculate the velocity of C, including its sign.', 'diagram:mom6-6-1-q18', 3, 'numeric'::answer_type, '0.3', 'm/s', false, NULL, true, '(a) A: 0.20 × 0.60 = +0.12 kg m s⁻¹. B: 0.30 × (−0.40) = −0.12 kg m s⁻¹. They add to zero. (b) So all of the total momentum belongs to C: 0.50 × v = +0.15, v = +0.30 m s⁻¹ (in the positive direction). Common mistake: adding the magnitudes of A and B (0.24) and getting a negative velocity for C.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('779d7b5a-428a-5632-b47b-08d89304f05f', '4fb48180-724d-4250-acde-e3277c2c9ed6', '196ffab0-6cca-4898-8909-a56000ff9fd7', 'as', '6.1', '9702 coursebook 6.1 · The idea of momentum', 19, 19, '(a) Show that the kinetic energy of an object of mass m and momentum p is Ek = p²/2m. A car of mass 1500 kg and a truck of mass 6000 kg each have momentum 3.0 × 10⁴ kg m s⁻¹. Both brake with the same constant braking force, 7500 N. (b) Calculate the kinetic energy of each. (c) Calculate the stopping distance of the car. (d) Show that both take the same time to stop. Give only the answer to (c).', 'diagram:mom6-6-1-q19', 4, 'numeric'::answer_type, '40', 'm', false, NULL, false, '(a) Ek = ½mv² = ½m(p/m)² = p²/2m. (b) Car: (3.0 × 10⁴)² ÷ (2 × 1500) = 3.00 × 10⁵ J. Truck: (3.0 × 10⁴)² ÷ (2 × 6000) = 75000 J. (c) The braking force does work F × d = Ek, so d = 3.00 × 10⁵ ÷ 7500 = 40 m (the truck needs only 10 m). (d) Force = rate of change of momentum, so t = Δp ÷ F = 3.0 × 10⁴ ÷ 7500 = 4.0 s for BOTH. Same momentum and same force means the same stopping TIME, but the lighter car, with four times the kinetic energy, travels four times as far. Common mistake: assuming equal momentum means equal stopping distance.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('60760248-381b-56d7-bb25-a4443842311a', '4fb48180-724d-4250-acde-e3277c2c9ed6', '196ffab0-6cca-4898-8909-a56000ff9fd7', 'as', '6.1', '9702 coursebook 6.1 · The idea of momentum', 20, 20, 'A sensor measures only the momentum and the kinetic energy of objects rolling past it. (a) Object X has momentum 6.0 kg m s⁻¹ and kinetic energy 15 J. Without being given either its mass or its speed, deduce its speed and its mass. (b) Object Y has TWICE the momentum of X but HALF its kinetic energy. Calculate the mass of Y. Give only the answer to (b).', NULL, 4, 'numeric'::answer_type, '9.6', 'kg', false, NULL, false, '(a) Ek = ½mv² = ½(mv)v = ½pv, so v = 2Ek/p = 2 × 15 ÷ 6.0 = 5.0 m s⁻¹, and m = p/v = 6.0 ÷ 5.0 = 1.2 kg (check: Ek = p²/2m = 36 ÷ 2.4 = 15 J). (b) m = p²/2Ek = (12)² ÷ (2 × 7.5) = 144 ÷ 15 = 9.6 kg — eight times the mass of X, because m ∝ p²/Ek and (2²) ÷ (½) = 8. Common mistake: assuming that doubling p and halving Ek simply doubles or halves the mass.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4672f73a-444e-567a-a2d8-964c830e2873', '4fb48180-724d-4250-acde-e3277c2c9ed6', '42c67aa7-36ea-56ea-881a-771edd16371c', 'as', '6.2', '9702 coursebook 6.2 · Conservation of momentum and collisions', 8, 8, 'An air-hockey puck of mass 0.30 kg moving at 5.0 m s⁻¹ hits a stationary puck of mass 0.20 kg head-on. After the collision the first puck continues in the same direction at 1.0 m s⁻¹. Calculate the speed of the second puck.', 'diagram:mom6-6-2-q8', 2, 'numeric'::answer_type, '6', 'm/s', false, NULL, false, 'Before: 0.30 × 5.0 = 1.5 kg m s⁻¹. After: 0.30 × 1.0 + 0.20 × v = 1.5, so 0.20v = 1.2 and v = 6.0 m s⁻¹. Common mistake: forgetting the first puck still carries momentum after the collision (giving 7.5 m s⁻¹).', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d7ca9fc1-d82e-592c-b030-5461ecf8c244', '4fb48180-724d-4250-acde-e3277c2c9ed6', '42c67aa7-36ea-56ea-881a-771edd16371c', 'as', '6.2', '9702 coursebook 6.2 · Conservation of momentum and collisions', 9, 9, 'A 2.0 kg trolley moving at 6.0 m s⁻¹ hits a stationary 4.0 kg trolley. The 2.0 kg trolley rebounds at 2.0 m s⁻¹. Calculate the speed of the 4.0 kg trolley after the collision.', 'diagram:mom6-6-2-q9', 2, 'numeric'::answer_type, '4', 'm/s', false, NULL, false, 'Take the original direction as positive. Before: 2.0 × 6.0 = +12 kg m s⁻¹. After: 2.0 × (−2.0) + 4.0v = 12, so 4.0v = 12 + 4.0 = 16 and v = 4.0 m s⁻¹. Common mistake: treating the rebound as +2.0 m s⁻¹, which gives 2.0 m s⁻¹ — the minus sign matters.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('cc3f21d5-e607-59d2-8e52-e58dc5c2c5a3', '4fb48180-724d-4250-acde-e3277c2c9ed6', '42c67aa7-36ea-56ea-881a-771edd16371c', 'as', '6.2', '9702 coursebook 6.2 · Conservation of momentum and collisions', 10, 10, 'An astronaut of total mass 85 kg is floating at rest 12 m from her spacecraft, with a broken thruster. She throws a 1.5 kg wrench directly away from the spacecraft at 6.0 m s⁻¹. Calculate how long it takes her to drift back to the spacecraft.', 'diagram:mom6-6-2-q10', 2, 'numeric'::answer_type, '113.3', 's', false, 0.05, false, 'Total momentum before = 0. After: 85v = 1.5 × 6.0 = 9.0 kg m s⁻¹, so she moves towards the spacecraft at v = 9.0 ÷ 85 = 0.106 m s⁻¹. Time = distance ÷ speed = 12 ÷ 0.106 = 113 s (about two minutes). Common mistake: using the wrench''s speed (6.0 m s⁻¹) for the astronaut.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('26e5a18f-1f88-53d2-82d2-fead6f1621c4', '4fb48180-724d-4250-acde-e3277c2c9ed6', '42c67aa7-36ea-56ea-881a-771edd16371c', 'as', '6.2', '9702 coursebook 6.2 · Conservation of momentum and collisions', 12, 12, 'A bullet of mass 12 g travelling at 350 m s⁻¹ embeds itself in a 2.0 kg wooden block resting on frictionless ice. Calculate the speed of the block (with the bullet inside) just afterwards.', 'diagram:mom6-6-2-q12', 2, 'numeric'::answer_type, '2.087', 'm/s', false, NULL, false, 'Before: 0.012 × 350 = 4.2 kg m s⁻¹. After, the mass is 2.0 + 0.012 = 2.012 kg: v = 4.2 ÷ 2.012 = 2.09 m s⁻¹. Common mistake: leaving 12 g as 12 kg in the calculation.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f44c157f-2d45-5650-afea-a4b34cfaacac', '4fb48180-724d-4250-acde-e3277c2c9ed6', '42c67aa7-36ea-56ea-881a-771edd16371c', 'as', '6.2', '9702 coursebook 6.2 · Conservation of momentum and collisions', 13, 13, 'A person of mass 50 kg stands on a stationary skateboard of negligible mass and catches a 4.0 kg medicine ball thrown horizontally at 6.0 m s⁻¹. Calculate the speed at which the person, skateboard and ball move off.', 'diagram:mom6-6-2-q13', 2, 'numeric'::answer_type, '0.4444', 'm/s', false, NULL, false, 'Before: 4.0 × 6.0 = 24 kg m s⁻¹ (the person has none). After, everything moves together: (50 + 4.0)v = 24, so v = 24 ÷ 54 = 0.444 m s⁻¹. Common mistake: dividing by 50 kg and forgetting that the ball is now moving with the person.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('019cb16c-6c78-5af2-bd0b-b0cdce8147fb', '4fb48180-724d-4250-acde-e3277c2c9ed6', '42c67aa7-36ea-56ea-881a-771edd16371c', 'as', '6.2', '9702 coursebook 6.2 · Conservation of momentum and collisions', 14, 14, 'In a motorway pile-up, car A (1000 kg) travelling at 18 m s⁻¹ runs into stationary car B (1200 kg) and they lock together. The pair then runs into stationary car C (800 kg) and all three lock together. Ignore friction during the collisions. (a) Calculate the speed of A and B just after the first collision. (b) Calculate the speed of all three just after the second collision. (c) Explain why the answer to (b) can be found without the answer to (a). Give only the answer to (b).', 'diagram:mom6-6-2-q14', 3, 'numeric'::answer_type, '6', 'm/s', false, NULL, false, '(a) 1000 × 18 = 2200 × v₁, v₁ = 8.18 m s⁻¹. (b) The momentum is still 18000 kg m s⁻¹: 3000 × v₂ = 18 000, v₂ = 6.0 m s⁻¹. (c) No external horizontal force acts at any stage, so the total momentum of the whole system (A + B + C) is the same at the end as at the start, whatever happens in between. Common mistake: carrying a rounded v₁ into part (b) and getting 5.98 or 6.02 instead of exactly 6.0.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c4d11fe4-c585-561d-bbbb-0df0e9342dce', '4fb48180-724d-4250-acde-e3277c2c9ed6', '42c67aa7-36ea-56ea-881a-771edd16371c', 'as', '6.2', '9702 coursebook 6.2 · Conservation of momentum and collisions', 15, 15, 'A student measures the speed of a toy dart. The 25 g dart is fired into a 0.475 kg trolley and sticks. Light gates show the trolley then covers 0.60 m in 1.5 s at constant speed. (a) Calculate the speed of the trolley after the impact. (b) Calculate the speed of the dart before the impact. Give only the answer to (b).', 'diagram:mom6-6-2-q15', 3, 'numeric'::answer_type, '8', 'm/s', false, NULL, false, '(a) v = 0.60 ÷ 1.5 = 0.40 m s⁻¹. (b) Combined mass = 0.025 + 0.475 = 0.50 kg. Momentum after = 0.500 × 0.40 = 0.20 kg m s⁻¹, which equals the dart''s momentum before: u = 0.20 ÷ 0.025 = 8.0 m s⁻¹. Common mistake: using the trolley''s mass alone (0.475 kg) instead of trolley + dart.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a22b0f30-7c32-5d0f-bff6-318906d3e27a', '4fb48180-724d-4250-acde-e3277c2c9ed6', '42c67aa7-36ea-56ea-881a-771edd16371c', 'as', '6.2', '9702 coursebook 6.2 · Conservation of momentum and collisions', 16, 16, 'Trolley A (0.80 kg) moving at 0.75 m s⁻¹ collides with a stationary trolley B of unknown mass. After the collision A moves backwards at 0.15 m s⁻¹ and B moves forwards at 0.45 m s⁻¹. (a) Write the momentum equation for the collision, with forwards positive. (b) Calculate the mass of B.', 'diagram:mom6-6-2-q16', 3, 'numeric'::answer_type, '1.6', 'kg', false, NULL, false, '(a) 0.80 × 0.75 + 0 = 0.80 × (−0.15) + m_B × 0.45. (b) 0.60 = −0.12 + 0.45 m_B, so 0.45 m_B = 0.72 and m_B = 1.6 kg. Common mistake: writing A''s final momentum as +0.12, which gives m_B = 1.1 kg.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('aee8d4c0-1017-57cf-bc98-4820eaddf945', '4fb48180-724d-4250-acde-e3277c2c9ed6', '42c67aa7-36ea-56ea-881a-771edd16371c', 'as', '6.2', '9702 coursebook 6.2 · Conservation of momentum and collisions', 17, 17, 'A 40 kg cart rolls along a frictionless track at 3.0 m s⁻¹. A 10 kg sack of sand is dropped vertically into the cart. (a) Calculate the speed of the cart after the sack lands in it. (b) Later, the sack falls straight down through a trapdoor in the floor of the moving cart. Calculate the speed of the cart after the sack has fallen out. Give only the answer to (b).', 'diagram:mom6-6-2-q17', 3, 'numeric'::answer_type, '2.4', 'm/s', false, NULL, false, '(a) The sack has no horizontal momentum, so horizontally: 40 × 3.0 = 50v, v = 2.4 m s⁻¹. (b) When the sack drops through the trapdoor it is moving horizontally with the cart, at 2.4 m s⁻¹, and it keeps that horizontal velocity as it leaves. Momentum after = 40v′ + 10 × 2.4 = 50 × 2.4, so v′ = 2.4 m s⁻¹: the cart does NOT speed back up. Common mistake: expecting the cart to return to 3.0 m s⁻¹ once the extra mass is gone.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f465a7aa-e88e-59bb-807b-8b4d98566335', '4fb48180-724d-4250-acde-e3277c2c9ed6', '42c67aa7-36ea-56ea-881a-771edd16371c', 'as', '6.2', '9702 coursebook 6.2 · Conservation of momentum and collisions', 18, 18, 'In a speed-skating relay, skater A (55 kg) moving at 4.0 m s⁻¹ catches up with team-mate B (65 kg) moving at 3.0 m s⁻¹ in the same direction, and pushes B forwards. Just after the push, B moves at 6.0 m s⁻¹. Friction is negligible. (a) Calculate the total momentum of the two skaters. (b) Calculate A''s velocity just after the push.', 'diagram:mom6-6-2-q18', 3, 'numeric'::answer_type, '0.4545', 'm/s', false, NULL, true, '(a) 55 × 4.0 + 65 × 3.0 = 220 + 195 = 415 kg m s⁻¹. (b) After: 55v_A + 65 × 6.0 = 415, so 55v_A = 415 − 390 = 25 and v_A = 0.455 m s⁻¹ — still forwards, but much slower. Common mistake: assuming A must stop or move backwards after pushing.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('cc7ce900-e70f-532b-bcd5-ffb00d38522e', '4fb48180-724d-4250-acde-e3277c2c9ed6', '42c67aa7-36ea-56ea-881a-771edd16371c', 'as', '6.2', '9702 coursebook 6.2 · Conservation of momentum and collisions', 19, 19, 'A 60 kg student sits on a 20 kg cart at rest on frictionless ice, holding three 5.0 kg bricks. She throws the bricks backwards one at a time, each at 8.0 m s⁻¹ relative to the ground. (a) Calculate the cart''s speed after the first throw. (b) Calculate its speed after all three throws. (c) Show that the answer to (b) is the same as if she had thrown all three bricks together at 8.0 m s⁻¹. Give only the answer to (b).', 'diagram:mom6-6-2-q19', 4, 'numeric'::answer_type, '1.5', 'm/s', false, NULL, false, ('Forwards positive' || chr(59) || ' the total momentum is zero throughout. (a) After throw 1: 90v₁ + 5.0 × (−8.0) = 0, v₁ = 40 ÷ 90 = 0.444 m s⁻¹. (b) Throw 2: 90 × 0.444 = 85v₂ − 40, v₂ = 0.941 m s⁻¹. Throw 3: 85 × 0.941 = 80v₃ − 40, v₃ = 1.5 m s⁻¹. (c) All three bricks end with momentum 3 × 5.0 × (−8.0) = −120 kg m s⁻¹, so the 80 kg student + cart must have +120: v = 120 ÷ 80 = 1.5 m s⁻¹, the same. (Because each speed is fixed relative to the GROUND, the order does not matter. A rocket is different: it ejects fuel at a fixed speed relative to ITSELF.) Common mistake: subtracting the mass of all three bricks before the first throw.'), 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f7db88b0-d956-5630-8a2b-eca3ccb7da5d', '4fb48180-724d-4250-acde-e3277c2c9ed6', '42c67aa7-36ea-56ea-881a-771edd16371c', 'as', '6.2', '9702 coursebook 6.2 · Conservation of momentum and collisions', 20, 20, 'Crash investigators reconstruct a rear-end collision. Car A (1100 kg) hit car B (1400 kg), which was stationary at traffic lights. The cars locked together and skidded 9.0 m to rest. Tests show that a skidding car on this road decelerates at 6.5 m s⁻². (a) Calculate the speed of the locked cars just after the impact. (b) Calculate the speed of car A just before the impact. (c) The speed limit is 50 km h⁻¹. Was car A speeding? Give only the answer to (b), in m s⁻¹.', 'diagram:mom6-6-2-q20', 4, 'numeric'::answer_type, '24.58', 'm/s', false, NULL, false, '(a) Skidding to rest: v² = u² + 2as gives 0 = v² − 2 × 6.5 × 9.0, so v = √117 = 10.8 m s⁻¹. (b) Momentum is conserved in the impact (it is so brief that friction does not change it noticeably): 1100u = 2500 × 10.8, u = 24.6 m s⁻¹. (c) 24.6 m s⁻¹ × 3.6 = 88.5 km h⁻¹: yes, well over 50 km h⁻¹. Common mistake: applying the skid to car A alone (1100 kg), or using the skid speed 10.8 m s⁻¹ as car A''s speed.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4848785f-c586-560c-aaa0-01d7ec9a5244', '4fb48180-724d-4250-acde-e3277c2c9ed6', 'ac47b348-a080-47b5-a3b9-a2a40915eb56', 'as', '6.3', '9702 coursebook 6.3 · Understanding collisions', 5, 5, 'In an inelastic car crash, kinetic energy is "lost". Where does it go?', NULL, 1, 'multiple_choice'::answer_type, 'Mostly into internal (thermal) energy, sound and the work done deforming the cars', NULL, false, NULL, false, 'Energy is always conserved overall. In an inelastic collision kinetic energy is transferred to other forms: internal energy (the materials heat up), sound, and the work done permanently deforming the cars. Common mistake: saying the energy is destroyed, or that it is turned into momentum (momentum is not a form of energy).', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c235de0d-7c46-5087-9566-cef30ea66c7b', '4848785f-c586-560c-aaa0-01d7ec9a5244', 'It is destroyed in the collision', 'A', false, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('19a0dfff-c405-5c2a-ac71-ae221596d0a4', '4848785f-c586-560c-aaa0-01d7ec9a5244', 'It is converted into extra momentum', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f3286526-cefc-594d-ab3e-2a1f04cd9e77', '4848785f-c586-560c-aaa0-01d7ec9a5244', 'It is stored as gravitational potential energy', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7b996e9c-97ae-551a-9b6b-58f58390e100', '4848785f-c586-560c-aaa0-01d7ec9a5244', 'Mostly into internal (thermal) energy, sound and the work done deforming the cars', 'D', true, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('af9a3957-face-5e9a-9306-078daa1bd4cc', '4fb48180-724d-4250-acde-e3277c2c9ed6', 'ac47b348-a080-47b5-a3b9-a2a40915eb56', 'as', '6.3', '9702 coursebook 6.3 · Understanding collisions', 7, 7, 'A 1.0 kg ball moving at 6.0 m s⁻¹ hits a stationary 2.0 kg ball. Afterwards the 1.0 kg ball rebounds at 2.0 m s⁻¹ and the 2.0 kg ball moves forwards at 4.0 m s⁻¹. Which conclusion is correct?', 'diagram:mom6-6-3-q7', 2, 'multiple_choice'::answer_type, 'Momentum and kinetic energy are both conserved, so the collision is elastic', NULL, false, NULL, false, ('Momentum: before 1.0 × 6.0 = 6.0' || chr(59) || ' after 1.0 × (−2.0) + 2.0 × 4.0 = 6.0 ✓. Kinetic energy: before ½ × 1.0 × 6.0² = 18 J' || chr(59) || ' after ½ × 1.0 × 2.0² + ½ × 2.0 × 4.0² = 2.0 + 16 = 18 J ✓. Both are conserved, so the collision is elastic. (Check: approach 6.0 m s⁻¹, separation 4.0 − (−2.0) = 6.0 m s⁻¹.) Common mistake: forgetting the rebound sign and deciding momentum is not conserved.'), 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('d60df1fb-550c-5834-97dd-380c79525e45', 'af9a3957-face-5e9a-9306-078daa1bd4cc', 'Momentum is conserved but kinetic energy is lost, so the collision is inelastic', 'A', false, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a08697f2-f3cb-5974-936b-f0189aa41096', 'af9a3957-face-5e9a-9306-078daa1bd4cc', 'Momentum and kinetic energy are both conserved, so the collision is elastic', 'B', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('0222bcda-900f-5434-b615-815d635664b3', 'af9a3957-face-5e9a-9306-078daa1bd4cc', 'Momentum is not conserved, so the data must be wrong', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('27f8b406-b100-5661-8924-a564bf315d7b', 'af9a3957-face-5e9a-9306-078daa1bd4cc', 'Kinetic energy is gained, so energy must have been released', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1b22b888-32be-504f-a676-8f34332440b6', '4fb48180-724d-4250-acde-e3277c2c9ed6', 'ac47b348-a080-47b5-a3b9-a2a40915eb56', 'as', '6.3', '9702 coursebook 6.3 · Understanding collisions', 9, 9, 'A snooker cue ball moving at 2.0 m s⁻¹ hits a stationary red ball of the same mass head-on. The collision is elastic. Calculate the speed of the red ball just afterwards.', 'diagram:mom6-6-3-q9', 2, 'numeric'::answer_type, '2', 'm/s', false, NULL, false, 'For equal masses in a head-on elastic collision with one at rest, the velocities are exchanged: the cue ball stops dead and the red moves off at 2.0 m s⁻¹. Check: momentum m × 2.0 = m × 0 + m × 2.0 ✓, KE ½m(2.0)² = ½m(2.0)² ✓, separation speed 2.0 = approach speed 2.0 ✓. This is how Newton''s cradle works. Common mistake: sharing the speed equally (1.0 m s⁻¹ each), which conserves momentum but loses half the kinetic energy.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0db04cfe-7d54-5e2d-9803-491b1959015e', '4fb48180-724d-4250-acde-e3277c2c9ed6', 'ac47b348-a080-47b5-a3b9-a2a40915eb56', 'as', '6.3', '9702 coursebook 6.3 · Understanding collisions', 10, 10, 'A 10 g bullet travelling at 300 m s⁻¹ embeds itself in a 1.99 kg block resting on a frictionless surface. Calculate the kinetic energy lost in the collision.', 'diagram:mom6-6-3-q10', 2, 'numeric'::answer_type, '447.8', 'J', false, NULL, false, 'Common velocity: 0.010 × 300 = 2.0 × v (combined mass 2.00 kg), v = 1.5 m s⁻¹. KE before = ½ × 0.010 × 300² = 450 J. KE after = ½ × 2.0 × 1.5² = 2.25 J. Lost = 448 J — over 99% of the bullet''s kinetic energy becomes internal energy of the bullet and block. Common mistake: assuming kinetic energy is conserved and using ½mv² to find the block''s speed.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('6d5faf5f-a0a2-5d0e-bd58-d649df9acbd2', '4fb48180-724d-4250-acde-e3277c2c9ed6', 'ac47b348-a080-47b5-a3b9-a2a40915eb56', 'as', '6.3', '9702 coursebook 6.3 · Understanding collisions', 11, 11, 'Which of these collisions is (to a very good approximation) perfectly elastic?', NULL, 2, 'multiple_choice'::answer_type, 'A collision between two gas molecules', NULL, false, NULL, false, 'Collisions between gas molecules are elastic: if kinetic energy were lost in every molecular collision, a gas in a sealed, insulated container would cool down on its own, and it does not. The other three all transfer kinetic energy to internal energy, sound and deformation. Common mistake: choosing the collision in which the objects bounce, without checking whether kinetic energy is actually kept.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f2372b80-d481-5b91-aed2-38674aa03147', '6d5faf5f-a0a2-5d0e-bd58-d649df9acbd2', 'A car crashing into a wall', 'A', false, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f9d74099-f0b4-5ab3-915e-8c83f43bfa39', '6d5faf5f-a0a2-5d0e-bd58-d649df9acbd2', 'A lump of modelling clay hitting the floor', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('51d2b558-8954-5a75-9150-cc7ae724a4ad', '6d5faf5f-a0a2-5d0e-bd58-d649df9acbd2', 'A collision between two gas molecules', 'C', true, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('91b9b7f3-6df6-58d6-918b-34b75effa009', '6d5faf5f-a0a2-5d0e-bd58-d649df9acbd2', 'A dart hitting a dartboard', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('7f7ff9bb-c143-5692-93e0-4ee06d54a212', '4fb48180-724d-4250-acde-e3277c2c9ed6', 'ac47b348-a080-47b5-a3b9-a2a40915eb56', 'as', '6.3', '9702 coursebook 6.3 · Understanding collisions', 12, 12, 'Two trolleys of mass 0.50 kg and 1.0 kg are held at rest with a compressed spring between them. When released, the 1.0 kg trolley moves off at 0.60 m s⁻¹. Calculate the total kinetic energy given to the trolleys by the spring.', 'diagram:mom6-6-3-q12', 2, 'numeric'::answer_type, '0.54', 'J', false, NULL, false, 'Total momentum stays zero: 0.50v = 1.0 × 0.60, so the 0.50 kg trolley moves the other way at 1.2 m s⁻¹. KE = ½ × 0.50 × 1.2² + ½ × 1.0 × 0.60² = 0.360 + 0.180 = 0.54 J. This kinetic energy came from the spring''s elastic potential energy: total kinetic energy INCREASES here, even though momentum is conserved. Common mistake: giving only the 1.0 kg trolley''s kinetic energy (0.18 J).', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e8647fdc-dac2-5721-adff-cdc83c6d4886', '4fb48180-724d-4250-acde-e3277c2c9ed6', 'ac47b348-a080-47b5-a3b9-a2a40915eb56', 'as', '6.3', '9702 coursebook 6.3 · Understanding collisions', 13, 13, 'Two balls of equal mass collide head-on and elastically. Before the collision ball A moves at +4.0 m s⁻¹ and ball B at −2.0 m s⁻¹. After the collision ball A moves at −2.0 m s⁻¹. Use the relative speed of separation to calculate the velocity of B after the collision.', 'diagram:mom6-6-3-q13', 2, 'numeric'::answer_type, '4', 'm/s', false, NULL, true, 'Relative speed of approach = 4.0 − (−2.0) = 6.0 m s⁻¹. Elastic, so relative speed of separation = 6.0 m s⁻¹: v_B − v_A = 6.0, v_B = −2.0 + 6.0 = +4.0 m s⁻¹. Check momentum: m(4.0) + m(−2.0) = 2.0m before, m(−2.0) + m(4.0) = 2.0m after ✓ (equal masses swap velocities). Common mistake: writing the separation as v_A − v_B, which gives −8.0 m s⁻¹.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('bfe33255-f5fe-5ba7-b112-e1686b7dae4a', '4fb48180-724d-4250-acde-e3277c2c9ed6', 'ac47b348-a080-47b5-a3b9-a2a40915eb56', 'as', '6.3', '9702 coursebook 6.3 · Understanding collisions', 14, 14, 'A 0.20 kg ball moving at 3.0 m s⁻¹ collides head-on and elastically with a stationary 0.10 kg ball. (a) Write down the momentum equation and the relative-speed equation for the collision. (b) Solve them to find the velocity of the 0.10 kg ball afterwards. (c) Check that kinetic energy is conserved. Give only the answer to (b).', 'diagram:mom6-6-3-q14', 3, 'numeric'::answer_type, '4', 'm/s', false, NULL, false, '(a) Momentum: 0.20 × 3.0 = 0.20v₁ + 0.10v₂. Relative speeds: v₂ − v₁ = 3.0. (b) From the second, v₁ = v₂ − 3.0. Substituting: 0.60 = 0.20(v₂ − 3.0) + 0.10v₂ = 0.30v₂ − 0.60, so v₂ = 4.0 m s⁻¹ (and v₁ = 1.0 m s⁻¹). (c) Before: ½ × 0.20 × 3.0² = 0.90 J. After: ½ × 0.20 × 1.0² + ½ × 0.10 × 4.0² = 0.10 + 0.80 = 0.90 J ✓. Common mistake: trying to solve with the KE equation (quadratic) when the relative-speed equation is linear and much quicker.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('91ee902d-f161-55b7-b153-7ba824817afc', '4fb48180-724d-4250-acde-e3277c2c9ed6', 'ac47b348-a080-47b5-a3b9-a2a40915eb56', 'as', '6.3', '9702 coursebook 6.3 · Understanding collisions', 15, 15, '(a) An object of mass m moving at speed u hits a stationary object of mass M and they stick together. Show that the fraction of the kinetic energy lost is M/(m + M). (b) A 1200 kg car travelling at 15 m s⁻¹ runs into the back of a stationary 1800 kg van and they lock together. Calculate the percentage of the car''s kinetic energy that is lost. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '60', '%', false, NULL, false, '(a) Common velocity v = mu/(m + M). KE after = ½(m + M)v² = ½m²u²/(m + M). Fraction kept = [½m²u²/(m + M)] ÷ [½mu²] = m/(m + M), so fraction lost = 1 − m/(m + M) = M/(m + M). (b) Fraction lost = 1800 ÷ 3000 = 0.60, i.e. 60%. (Check: v = 18 000 ÷ 3000 = 6.0 m s⁻¹, KE 1.35 × 10⁵ J → 54000 J.) The heavier the stationary object, the larger the share of kinetic energy lost. Common mistake: using m/(m + M) = 40%, which is the fraction KEPT.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d4dab58c-1654-584b-86af-beaca04b683a', '4fb48180-724d-4250-acde-e3277c2c9ed6', 'ac47b348-a080-47b5-a3b9-a2a40915eb56', 'as', '6.3', '9702 coursebook 6.3 · Understanding collisions', 16, 16, 'A student claims that a 3.0 kg ball moving at 4.0 m s⁻¹ hit a stationary 1.0 kg ball, which then moved off at 7.0 m s⁻¹. Use conservation of momentum to find the 3.0 kg ball''s speed afterwards, then compare the kinetic energies. What can you conclude?', 'diagram:mom6-6-3-q16', 3, 'multiple_choice'::answer_type, 'The claim is impossible for a simple collision: the kinetic energy would increase', NULL, false, NULL, false, 'Momentum: 3.0 × 4.0 = 3.0v + 1.0 × 7.0, so v = 5.0 ÷ 3.0 = 1.67 m s⁻¹. KE before = ½ × 3.0 × 4.0² = 24 J. KE after = ½ × 3.0 × 1.67² + ½ × 1.0 × 7.0² = 4.17 + 24.5 = 28.7 J. The kinetic energy would have INCREASED, which is impossible for a simple collision: energy would have to come from somewhere, e.g. a compressed spring or an explosive charge. (Relative speeds agree: approach 4.0 m s⁻¹, separation 7.0 − 1.67 = 5.33 m s⁻¹ — faster than approach.) Common mistake: checking only momentum and accepting the claim.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('fe12b161-0eed-562c-b15a-ffe5a959b96d', 'd4dab58c-1654-584b-86af-beaca04b683a', 'The claim is impossible for a simple collision: the kinetic energy would increase', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8404ce2d-8f11-5e15-a590-7fd47c88d09d', 'd4dab58c-1654-584b-86af-beaca04b683a', 'The collision is elastic: momentum and kinetic energy are both conserved', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('eeedfd11-1ecf-59d4-a500-fb8c3d594f06', 'd4dab58c-1654-584b-86af-beaca04b683a', 'The collision is inelastic: some kinetic energy is lost', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ac2a1873-e9ca-5e59-a980-461ce9e23a7b', 'd4dab58c-1654-584b-86af-beaca04b683a', 'The claim is impossible because momentum is not conserved', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('99d665ca-4f58-5819-92d8-048867ee127d', '4fb48180-724d-4250-acde-e3277c2c9ed6', 'ac47b348-a080-47b5-a3b9-a2a40915eb56', 'as', '6.3', '9702 coursebook 6.3 · Understanding collisions', 17, 17, 'A ball is dropped from a height of 2.0 m onto a hard floor and bounces back up to 1.2 m. Air resistance is negligible. (a) Calculate the percentage of the ball''s kinetic energy lost during the bounce. (b) Calculate the ratio (speed just after the bounce) ÷ (speed just before). (c) Is the ball–floor collision elastic? Give only the answer to (a).', 'diagram:mom6-6-3-q17', 3, 'numeric'::answer_type, '40', '%', false, NULL, false, '(a) Just before impact Ek = mg × 2.0, just after Ek = mg × 1.2 (all of it becomes potential energy at the top). Fraction lost = (2.0 − 1.2) ÷ 2.0 = 0.40, i.e. 40%. (b) Ek ∝ v², so v_after/v_before = √(1.2/2.0) = 0.775. (c) No — it is inelastic, because kinetic energy is lost (to internal energy and sound). Momentum of ball + Earth is still conserved. Common mistake: taking the speed ratio as 1.2/2.0 = 0.60 — heights are proportional to v², not v.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b9732a05-cdbb-5259-ae5a-67de709d606e', '4fb48180-724d-4250-acde-e3277c2c9ed6', 'ac47b348-a080-47b5-a3b9-a2a40915eb56', 'as', '6.3', '9702 coursebook 6.3 · Understanding collisions', 18, 18, 'A ballistic pendulum measures the speed of an air-rifle pellet. The 15 g pellet embeds in a 1.485 kg block hanging from light strings, and the block swings up through a vertical height of 8.0 cm. (a) Calculate the speed of the block just after the impact. (b) Calculate the speed of the pellet. (c) Explain why kinetic energy is conserved during the swing but NOT during the impact. Give only the answer to (b).', 'diagram:mom6-6-3-q18', 3, 'numeric'::answer_type, '125.3', 'm/s', false, 0.05, false, '(a) During the swing kinetic energy becomes gravitational potential energy: ½mv² = mgh, v = √(2gh) = √(2 × 9.81 × 0.080) = 1.25 m s⁻¹. (b) Momentum is conserved in the impact: 0.015 × u = 1.500 × 1.25, u = 125 m s⁻¹. (c) The impact is perfectly inelastic: about 99% of the pellet''s kinetic energy becomes internal energy. During the swing only gravity does work (the string tension is perpendicular to the motion), so mechanical energy is conserved there. Common mistake: equating the pellet''s kinetic energy directly to mgh, which gives about 13 m s⁻¹, far too small.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d376b0d6-1ef2-5640-a2eb-d04f47034f64', '4fb48180-724d-4250-acde-e3277c2c9ed6', 'ac47b348-a080-47b5-a3b9-a2a40915eb56', 'as', '6.3', '9702 coursebook 6.3 · Understanding collisions', 19, 19, '(a) A particle of mass m₁ moving at u collides head-on and elastically with a stationary particle of mass m₂. Show that its velocity afterwards is v₁ = (m₁ − m₂)u/(m₁ + m₂). (b) In a nuclear reactor, fast neutrons are slowed by elastic collisions with moderator nuclei. A neutron (mass 1.0 u) collides head-on with a stationary carbon-12 nucleus (mass 12 u). Calculate the percentage of the neutron''s kinetic energy transferred to the carbon nucleus. (c) Explain why hydrogen-rich water slows neutrons in far fewer collisions. Give only the answer to (b).', 'diagram:mom6-6-3-q19', 4, 'numeric'::answer_type, '28.4', '%', false, NULL, false, '(a) Momentum: m₁u = m₁v₁ + m₂v₂. Relative speeds (elastic): v₂ − v₁ = u, so v₂ = u + v₁. Substituting: m₁u = m₁v₁ + m₂u + m₂v₁, so v₁(m₁ + m₂) = (m₁ − m₂)u and v₁ = (m₁ − m₂)u/(m₁ + m₂). (b) v₁/u = (1 − 12)/(1 + 12) = −11/13, so the fraction of KE the neutron keeps = (11/13)² = 0.716. Transferred = 1 − 0.716 = 0.284, i.e. 28.4%. (c) A hydrogen nucleus (a proton) has almost the same mass as a neutron, so m₁ − m₂ ≈ 0: in a head-on collision the neutron stops and passes nearly ALL its kinetic energy on, just like equal snooker balls. Common mistake: using the speed ratio 11/13 as the energy ratio — kinetic energy goes with v², so square it.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('7921c7fb-3c95-545e-8649-607082242f25', '4fb48180-724d-4250-acde-e3277c2c9ed6', 'ac47b348-a080-47b5-a3b9-a2a40915eb56', 'as', '6.3', '9702 coursebook 6.3 · Understanding collisions', 20, 20, 'A tennis ball rests on top of a basketball and the pair is dropped from a height of 1.2 m (measured to the bottom of the basketball). The basketball''s mass is much larger than the tennis ball''s, and every collision is elastic. The basketball bounces off the floor first and, moving upwards, immediately meets the tennis ball, which is still moving downwards. (a) Calculate the speed of both balls just before the basketball hits the floor. (b) Use relative speeds to show that the tennis ball leaves the basketball at three times this speed. (c) Calculate the ideal height the tennis ball rises to, measured from where it leaves the basketball. Give only the answer to (c).', 'diagram:mom6-6-3-q20', 4, 'numeric'::answer_type, '10.8', 'm', false, 0.05, false, '(a) v = √(2gh) = √(2 × 9.81 × 1.2) = 4.85 m s⁻¹, downwards, for both. (b) The basketball rebounds elastically from the floor at 4.85 m s⁻¹ upwards. The tennis ball is still moving down at 4.85 m s⁻¹, so the relative speed of approach is 2 × 4.85 = 9.70 m s⁻¹. Elastic, so it separates at 9.70 m s⁻¹ RELATIVE TO the basketball, and the much heavier basketball is barely affected and still moves up at 4.85 m s⁻¹. Tennis ball speed = 4.85 + 9.70 = 14.6 m s⁻¹ = 3v. (c) h = v²/2g = 14.6² ÷ (2 × 9.81) = 10.8 m — nine times the drop height, because h ∝ v² and 3² = 9. (Real balls lose energy, so they rise less, but the effect is still dramatic.) Common mistake: assuming the tennis ball can at most return to 1.2 m, or adding speeds as 2v rather than v + 2v.', 6) ON CONFLICT (id) DO NOTHING;
